import re
from build_lib import *
FIG='../figures/'
MEDIA='../figures/src/'
D=Doc(body_pt=12, line=1.1, indent_cm=1.0, text_width_cm=17.0)
H=D.heading
# ---------------- automatic numbering: figures, tables, equations are referenced by label
FIGS=['setup','brake','exp','proc','modes','ident','spring','eff','scan','pareto','time']
TABS=['tests','osc','modal','ident','spring','layouts','robust','energy','summary']
EQS=['X','xd','zeta','ext','dT','Ke','eig','ks','motion','pulse','lsq','AL','K1','N',
     'vj','sgn','int','eta','kappa','zT','jenk','energy','NJ','opt']
_LISTS={'f':FIGS,'t':TABS,'e':EQS}
def R(s):
    return re.sub(r'\{([fte]):(\w+)\}', lambda m: str(_LISTS[m.group(1)].index(m.group(2))+1), s)
def P(text, **k): return D.para(R(text), **k)
def FIGR(label, path, width, caption):
    n=D.figure(path, width, R(caption)); assert n==FIGS.index(label)+1, (label, n)
def TAB(label, caption, header, rows, widths, **k):
    D.table(R(caption), [[R(c) for c in r] for r in header], [[R(c) for c in r] for r in rows], widths, **k)
    assert D.tab==TABS.index(label)+1, (label, D.tab)
_eq=[0]
def EQ(latex, label):
    _eq[0]+=1; assert EQS[_eq[0]-1]==label, (label, _eq[0]); D.eq(latex, _eq[0])
